import{G as e,K as t,at as n,j as r}from"./chunks/framework.DrNIf5Lg.js";var i=JSON.parse(`{"title":"Doctor 环境检查","description":"","frontmatter":{},"headers":[],"relativePath":"zh/develop/doctor-module.md","filePath":"zh/develop/doctor-module.md"}`),a={name:`zh/develop/doctor-module.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="doctor-环境检查" tabindex="-1">Doctor 环境检查 <a class="header-anchor" href="#doctor-环境检查" aria-label="Permalink to “Doctor 环境检查”">​</a></h1><p>Doctor 用于诊断当前宿主机、选定 target 和编译器 toolchain 能否运行 StaticPHP 构建流水线。它会检查通用宿主机命令、平台专属 SDK、受 StaticPHP 管理的 Tool Package，以及 Zig、musl 等与所选目标相关的前置条件。</p><h2 id="运行-doctor" tabindex="-1">运行 Doctor <a class="header-anchor" href="#运行-doctor" aria-label="Permalink to “运行 Doctor”">​</a></h2><p>安装 StaticPHP、修改 target/toolchain 或更新系统构建工具后，应显式运行 Doctor：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 预构建二进制</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./spc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 源码安装</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin/spc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>通过 <code>--auto-fix</code>（<code>-y</code>）选择修复策略：</p><table tabindex="0"><thead><tr><th>调用方式</th><th>当前行为</th></tr></thead><tbody><tr><td><code>spc doctor</code></td><td>每个可自动修复的项目执行前都询问</td></tr><tr><td><code>spc doctor --auto-fix</code></td><td>不询问，直接执行可用修复</td></tr><tr><td><code>spc doctor --auto-fix=never</code></td><td>报告第一个未解决的失败，不尝试修复</td></tr></tbody></table><p>只有每个适用检查都通过、被跳过，或者返回了当前实现认为成功的修复时，Doctor 才会成功退出。它会在第一个未解决的失败处停止。</p><p><code>craft</code> 命令默认也会运行 Doctor，并使用不询问的自动修复策略；可以在 <code>craft.yml</code> 中设置 <code>craft-options.doctor: false</code> 禁用该步骤。</p><h2 id="执行模型" tabindex="-1">执行模型 <a class="header-anchor" href="#执行模型" aria-label="Permalink to “执行模型”">​</a></h2><p>当前执行顺序如下：</p><ol><li><code>DoctorLoader</code> 收集内置 class 和 Registry 提供的 class，扫描其 public method 上的 Doctor Attribute。</li><li>按 <code>level</code> 从高到低排序检查。</li><li>通过 <code>#[OptionalCheck]</code>、<code>limit_os</code> 和 <code>SPC_SKIP_DOCTOR_CHECK_ITEMS</code> 排除不适用检查。</li><li>直接调用 check callback。</li><li><code>null</code> 表示跳过；<code>CheckResult::ok()</code> 表示通过；<code>CheckResult::fail()</code> 描述失败，并可指定一个 fix。</li><li>根据修复策略，Doctor 会拒绝、询问或立即通过 <code>ApplicationContext</code> 调用指定 fix。</li></ol><p><code>checkAll()</code> 采用 fail-fast：它不会收集全部失败后再输出汇总。Fixer 成功后，当前实现也不会重新运行原 check。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>无效的 check 返回值当前会显示“Skipped due to invalid return value”，并被当作成功。这是实现限制，扩展作者不应依赖该行为。</p></div><h2 id="内置检查分组" tabindex="-1">内置检查分组 <a class="header-anchor" href="#内置检查分组" aria-label="Permalink to “内置检查分组”">​</a></h2><p>实际检查清单随所选 target 变化。当前 core Registry 提供以下分组：</p><table tabindex="0"><thead><tr><th>范围</th><th>检查内容</th></tr></thead><tbody><tr><td>通用</td><td>至少加载了一个 Registry；宿主 OS 是 Linux、macOS 或 Windows</td></tr><tr><td>Linux</td><td>发行版构建工具基线、CMake 3.22+、<code>re2c</code> 1.0.3+，以及 musl 发行版的 Linux headers</td></tr><tr><td>macOS</td><td>Homebrew 或 MacPorts、必需构建命令、GNU Bison 3+，以及选定的 Homebrew/MacPorts LLVM 变体</td></tr><tr><td>Windows target</td><td><code>vswhere</code>、Visual Studio C++ 工具、Git <code>patch.exe</code>、受管理的 MSYS2、<code>7za.exe</code> 和初始化后的 MSVC 命令环境</td></tr><tr><td>Unix target</td><td>由 StaticPHP 管理且可以正常执行的 <code>pkg-config</code></td></tr><tr><td>Zig toolchain</td><td>已安装 StaticPHP 的 <code>zig</code> Tool Package</td></tr><tr><td>musl target/toolchain</td><td>所需的 musl wrapper；旧式 <code>MuslToolchain</code> 还需要 <code>/usr/local/musl</code> 下的交叉工具链</td></tr></tbody></table><p>Package 通过 <code>tools</code> 字段声明的专用工具由 <code>PackageInstaller</code> 解析，不会全部重复列入 Doctor 基线检查。各平台软件包清单和 toolchain 细节参见<a href="./system-build-tools.html">编译工具</a>。</p><h2 id="自动修复" tabindex="-1">自动修复 <a class="header-anchor" href="#自动修复" aria-label="Permalink to “自动修复”">​</a></h2><p>根据失败项目和平台，fix 可能会：</p><ul><li>调用 <code>apt</code>、<code>apk</code>、<code>dnf</code>、<code>yum</code>、<code>pacman</code>、Homebrew 或 MacPorts。</li><li>使用 <code>sudo</code> 安装系统级内容。</li><li>下载并安装 StaticPHP Tool 或 Artifact Package。</li><li>构建 <code>re2c</code> 等替代工具。</li><li>在工作区之外安装 musl runtime 或交叉工具链文件。</li></ul><p>因此，自动修复可能访问网络并修改宿主系统。默认交互策略会先询问；CI 通常在一次性环境中使用 <code>--auto-fix</code>，或在预配置镜像中使用 <code>--auto-fix=never</code>。</p><p>Fixer 之间没有共享事务或回滚机制。Fixer 返回 <code>true</code> 后，当前实现即认为修复成功，即使环境仍不满足原条件。需要确认时，应在修复后重新运行 <code>spc doctor --auto-fix=never</code>。</p><h2 id="doctor-lock" tabindex="-1">Doctor Lock <a class="header-anchor" href="#doctor-lock" aria-label="Permalink to “Doctor Lock”">​</a></h2><p>所有检查被视为成功后，Doctor 会写入 <code>.spc-doctor.lock</code>，内容为当前 StaticPHP 版本。<code>craft</code> 的 Doctor 步骤成功后也会写入同一 lock。</p><p>首选位置如下：</p><table tabindex="0"><thead><tr><th>平台</th><th>首选路径</th><th>回退位置</th></tr></thead><tbody><tr><td>Unix</td><td><code>$XDG_CACHE_HOME/.spc-doctor.lock</code>，或 <code>$HOME/.cache/.spc-doctor.lock</code></td><td>系统临时目录，然后是工作目录</td></tr><tr><td>Windows</td><td><code>%LOCALAPPDATA%\\.spc-doctor.lock</code></td><td>系统临时目录，然后是工作目录</td></tr></tbody></table><p>调用 <code>checkDoctorCache()</code> 的构建/下载命令只使用该 lock 决定是否显示警告。Lock 不会跳过显式的 <code>spc doctor</code>，也不会阻止构建。</p><p>当前 fingerprint 只有 StaticPHP 版本。target、toolchain、Registry 集合、PATH 或操作系统发生变化时，lock 不会自动失效。此类变化后应删除 lock 或显式运行 Doctor。</p><h2 id="跳过检查和警告" tabindex="-1">跳过检查和警告 <a class="header-anchor" href="#跳过检查和警告" aria-label="Permalink to “跳过检查和警告”">​</a></h2><p>两个环境变量用途不同：</p><div class="language-ini"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 在实际 Doctor 运行中跳过指定项目（使用完整项目名，逗号分隔）</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">SPC_SKIP_DOCTOR_CHECK_ITEMS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;if cmake version &gt;= 3.22,if re2c version &gt;= 1.0.3&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Doctor lock 缺失或过期时，不显示构建前警告</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">SPC_SKIP_DOCTOR_CHECK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span></code></pre></div><p><code>SPC_SKIP_DOCTOR_CHECK</code> 不会从显式 <code>spc doctor</code> 中移除检查。<code>SPC_SKIP_DOCTOR_CHECK_ITEMS</code> 会；跳过必要检查可能让不可用的环境看起来健康，因此只应在受控 CI 或调试场景中使用。</p><h2 id="当前内部注册模型" tabindex="-1">当前内部注册模型 <a class="header-anchor" href="#当前内部注册模型" aria-label="Permalink to “当前内部注册模型”">​</a></h2><p>Registry 当前可以通过 <code>doctor.psr-4</code> 或 <code>doctor.classes</code> 指向 PHP class。<code>DoctorLoader</code> 会以无参数构造这些 class，并识别：</p><table tabindex="0"><thead><tr><th>Attribute</th><th>当前作用</th></tr></thead><tbody><tr><td><code>#[CheckItem]</code></td><td>注册检查名、可选 OS 限制和数字 level；level 越高越先执行</td></tr><tr><td><code>#[OptionalCheck]</code></td><td>提供 class 或 method 级 callable，决定该检查是否存在</td></tr><tr><td><code>#[FixItem]</code></td><td>注册字符串 fix 名，由失败的 <code>CheckResult</code> 引用</td></tr></tbody></table><p>Check callback 当前不接收 DI context，返回 <code>null</code> 或 <code>CheckResult</code>。Fix callback 通过 <code>ApplicationContext</code> 调用，并把 <code>CheckResult</code> 的原始 <code>fix_params</code> 数组作为 callback context。<code>CheckItem</code> 的 <code>manual</code> 属性当前未被执行器使用。</p>`,37)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};